function countOneSquares(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  let total = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    for (let k = 1; r + k <= R && c + k <= C; k++) {
      let ok = true;
      // new bottom row and right column of the k×k square
      for (let i = 0; i < k && ok; i++) {
        if (grid[r + k - 1][c + i] === 0 || grid[r + i][c + k - 1] === 0) ok = false;
      }
      if (!ok) break;
      total++;
    }
  }
  return total;
}

