class Solution:
    def countOneSquares(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        total = 0
        for r in range(R):
            for c in range(C):
                k = 1
                while r + k <= R and c + k <= C:
                    if any(grid[r + k - 1][c + i] == 0 or grid[r + i][c + k - 1] == 0 for i in range(k)):
                        break
                    total += 1
                    k += 1
        return total

