function countOneSquares(grid: number[][]): number {
  const C = grid[0].length;
  let prev = new Array<number>(C).fill(0), total = 0;
  for (const row of grid) {
    const cur = new Array<number>(C).fill(0);
    for (let c = 0; c < C; c++) {
      if (row[c] === 0) continue;
      cur[c] = c === 0 ? 1 : 1 + Math.min(prev[c], cur[c - 1], prev[c - 1]);
      total += cur[c];
    }
    prev = cur;
  }
  return total;
}

